import numpy as np


class AnytimeCompassArchiveJADE:
    """
    Feasibility-rule JADE with external archive (current-to-pbest/1) and Lehmer-mean F adaptation.
    Anytime refinement of the incumbent alternates a coordinate compass (pattern) search, which
    exploits axis-aligned structure of engineering constraints, with a heavy-tailed 1/5-rule
    Gaussian search. The population is smaller for low dimension to speed up early progress,
    and restarts seed around the incumbent with a radius that shrinks as stagnation persists.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = budget
        self.dim = dim

    def __call__(self, func):
        rng = np.random.default_rng()
        d = self.dim
        lb = np.asarray(func.bounds.lb, dtype=float)
        ub = np.asarray(func.bounds.ub, dtype=float)
        vt = list(func.variable_types)
        disc = np.array([t != "continuous" for t in vt], dtype=bool)
        disc_idx = np.where(disc)[0]
        cont_idx = np.where(~disc)[0]
        nv = np.ones(d)
        if disc.any():
            nv[disc] = np.asarray(func.n_values, dtype=float)[disc]
        pm = 1.0 / d

        cache = {}
        st = {"used": 0, "best_f": np.inf, "best_x": None,
              "ref_x": None, "ref_res": None}

        def decode(u):
            x = lb + u * (ub - lb)
            if disc.any():
                x[disc] = np.rint(u[disc] * (nv[disc] - 1.0))
            return np.clip(x, lb, ub)

        def better(a, b):
            if a[1] == 0.0 and b[1] == 0.0:
                return a[0] < b[0]
            if a[1] == 0.0 or b[1] == 0.0:
                return a[1] == 0.0
            return a[1] < b[1]

        def evaluate(u):
            x = decode(u)
            key = tuple(x.tolist())
            if key in cache:
                return cache[key]
            if st["used"] >= self.budget:
                return None
            f, g = func(x)
            st["used"] += 1
            f = float(f)
            if not np.isfinite(f):
                f = 1e30
            g = np.atleast_1d(np.asarray(g, dtype=float))
            g = np.nan_to_num(g, nan=1e6, posinf=1e6, neginf=0.0)
            viol = float(np.sum(np.maximum(g, 0.0)))
            res = (f, viol)
            cache[key] = res
            if viol == 0.0 and f < st["best_f"]:
                st["best_f"] = f
                st["best_x"] = x.copy()
            if st["ref_res"] is None or better(res, st["ref_res"]):
                st["ref_res"] = res
                st["ref_x"] = x.copy()
            return res

        def lhs(n):
            U = np.empty((n, d))
            for j in range(d):
                U[:, j] = (rng.permutation(n) + rng.random(n)) / n
            return U

        def reflect(v):
            v = np.where(v < 0.0, -v, v)
            v = np.where(v > 1.0, 2.0 - v, v)
            return np.clip(v, 0.0, 1.0)

        def disc_neighbour_move(u, p):
            for k in disc_idx:
                if rng.random() < p:
                    n_k = int(nv[k])
                    if n_k > 1:
                        if rng.random() < 0.6:
                            step = 1 if rng.random() < 0.5 else -1
                            idx = int(np.rint(u[k] * (n_k - 1))) + step
                            idx = min(max(idx, 0), n_k - 1)
                        else:
                            idx = int(rng.integers(n_k))
                        u[k] = idx / (n_k - 1.0)
            return u

        def finish():
            if st["best_x"] is not None:
                return st["best_f"], st["best_x"]
            if st["ref_x"] is not None:
                return st["ref_res"][0], st["ref_x"]
            return np.inf, None

        NP = int(np.clip(4 * d, 12, 60))
        NP = max(6, min(NP, max(6, self.budget // 8)))

        def make_population(seeds=None):
            n_seed = 0 if seeds is None else len(seeds)
            U = lhs(NP)
            if n_seed:
                U[:n_seed] = np.asarray(seeds)
            R = [None] * NP
            for i in range(NP):
                res = evaluate(U[i])
                if res is None:
                    return None, None
                R[i] = res
            return U, R

        def pop_best(R):
            b = 0
            for i in range(1, len(R)):
                if better(R[i], R[b]):
                    b = i
            return b

        def gauss_ls(u0, r0, n_eval):
            cur_u, cur_r = u0.copy(), r0
            sigma = 0.08
            succ = 0
            for t in range(n_eval):
                cand = cur_u.copy()
                if len(cont_idx) > 0:
                    if rng.random() < 0.15:
                        step = np.clip(0.05 * rng.standard_cauchy(len(cont_idx)), -0.5, 0.5)
                        cand[cont_idx] += step
                    else:
                        mask = rng.random(len(cont_idx)) < max(1.0 / len(cont_idx), 0.3)
                        if not mask.any():
                            mask[rng.integers(len(cont_idx))] = True
                        cand[cont_idx] += sigma * rng.standard_normal(len(cont_idx)) * mask
                cand = disc_neighbour_move(cand, 1.0 / d)
                cand = np.clip(cand, 0.0, 1.0)
                res = evaluate(cand)
                if res is None:
                    return cur_u, cur_r, True
                if better(res, cur_r):
                    cur_u, cur_r = cand, res
                    succ += 1
                if (t + 1) % 5 == 0:
                    rate = succ / 5.0
                    sigma *= 1.3 if rate > 0.2 else 0.8
                    sigma = float(np.clip(sigma, 1e-4, 0.3))
                    succ = 0
            return cur_u, cur_r, False

        def compass_search(u0, r0, n_eval):
            # Coordinate pattern search: +/- moves along each variable, step halving on failure.
            cur_u, cur_r = u0.copy(), r0
            step = 0.05
            used_local = 0
            while used_local < n_eval:
                improved = False
                for k in rng.permutation(d):
                    for s in (1.0, -1.0):
                        if used_local >= n_eval:
                            break
                        cand = cur_u.copy()
                        if disc[k]:
                            dk = 1.0 / max(nv[k] - 1.0, 1.0)
                        else:
                            dk = step
                        cand[k] = np.clip(cand[k] + s * dk, 0.0, 1.0)
                        res = evaluate(cand)
                        if res is None:
                            return cur_u, cur_r, True
                        used_local += 1
                        if better(res, cur_r):
                            cur_u, cur_r = cand, res
                            improved = True
                            break
                    if used_local >= n_eval:
                        break
                if not improved:
                    step *= 0.5
                    if step < 1e-3:
                        step = 0.02 + 0.1 * rng.random()
            return cur_u, cur_r, False

        # Initial population
        U, R = make_population()
        if U is None:
            return finish()

        A = []
        mu_F, mu_CR = 0.5, 0.5
        c = 0.1
        ls_period = 3
        ls_budget = max(12, 4 * d)
        cs_budget = max(10, 3 * d)
        prev_best = R[pop_best(R)]
        gen_since_imp = 0
        gen = 0
        stall_limit = 15
        restarts = 0

        while st["used"] < self.budget:
            gen += 1
            new_before = st["used"]
            order = sorted(range(NP), key=lambda k: (R[k][1], R[k][0]))
            SF, SCR = [], []
            out = False

            for i in range(NP):
                F = -1.0
                for _ in range(20):
                    F = mu_F + 0.1 * np.tan(np.pi * (rng.random() - 0.5))
                    if F > 0:
                        break
                F = min(1.0, F) if F > 0 else 0.1
                CR = float(np.clip(rng.normal(mu_CR, 0.1), 0.0, 1.0))

                p = max(2, int(rng.uniform(0.05, 0.2) * NP))
                pb = order[rng.integers(p)]
                others = [k for k in range(NP) if k != i and k != pb]
                r1 = others[rng.integers(len(others))]
                pool_n = NP + len(A)
                r2 = rng.integers(pool_n)
                while r2 == i or r2 == r1:
                    r2 = rng.integers(pool_n)
                xr2 = U[r2] if r2 < NP else A[r2 - NP]

                mutant = reflect(U[i] + F * (U[pb] - U[i]) + F * (U[r1] - xr2))

                trial = U[i].copy()
                mask = rng.random(d) < CR
                mask[rng.integers(d)] = True
                trial[mask] = mutant[mask]
                trial = disc_neighbour_move(trial, pm)
                trial = np.clip(trial, 0.0, 1.0)

                res = evaluate(trial)
                if res is None:
                    out = True
                    break
                if better(res, R[i]):
                    if len(A) < NP:
                        A.append(U[i].copy())
                    else:
                        A[rng.integers(NP)] = U[i].copy()
                    SF.append(F)
                    SCR.append(CR)
                    U[i] = trial
                    R[i] = res
                elif res == R[i]:
                    U[i] = trial
                    R[i] = res

            if out:
                break

            if SF:
                sf = np.asarray(SF)
                mu_F = (1 - c) * mu_F + c * (np.sum(sf ** 2) / max(np.sum(sf), 1e-12))
                mu_CR = (1 - c) * mu_CR + c * float(np.mean(SCR))

            # Alternating incumbent refinement: compass search and 1/5-rule Gaussian search
            if gen % ls_period == 0 and st["used"] < self.budget:
                b = pop_best(R)
                if (gen // ls_period) % 2 == 0:
                    cur_u, cur_r, out = compass_search(U[b], R[b], cs_budget)
                else:
                    cur_u, cur_r, out = gauss_ls(U[b], R[b], ls_budget)
                worst = max(range(NP), key=lambda k: (R[k][1], R[k][0]))
                if better(cur_r, R[worst]):
                    U[worst] = cur_u
                    R[worst] = cur_r
                if out:
                    break

            cur_best = R[pop_best(R)]
            if better(cur_best, prev_best):
                if cur_best[0] < prev_best[0] - 1e-12 or cur_best[1] < prev_best[1] - 1e-12:
                    gen_since_imp = 0
                prev_best = cur_best
            else:
                gen_since_imp += 1

            saturated = st["used"] == new_before
            if gen_since_imp >= stall_limit or saturated:
                restarts += 1
                b = pop_best(R)
                inc_u = U[b].copy()
                # Seed radius shrinks with the number of restarts (local exploitation)
                radius = max(0.01, 0.08 / np.sqrt(restarts))
                n_seed = NP // 2
                seeds = []
                for _ in range(n_seed):
                    s = inc_u.copy()
                    if len(cont_idx) > 0:
                        s[cont_idx] += radius * rng.standard_normal(len(cont_idx))
                    s = disc_neighbour_move(s, 2.0 / d)
                    seeds.append(np.clip(s, 0.0, 1.0))
                seeds.insert(0, inc_u)
                seeds = seeds[:NP]
                U_new, R_new = make_population(seeds)
                if U_new is None:
                    break
                U, R = U_new, R_new
                A = []
                mu_F, mu_CR = 0.5, 0.5
                prev_best = R[pop_best(R)]
                gen_since_imp = 0

        return finish()
